import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.*;

public class Main {
    static final long MOD = 1000000007L;

    // 计算答案的函数
    static long solve(int n, long[] a) {
        // f[i] 表示长度为 i 的线性序列中，选若干个互不相邻位置的方案数（可一个不选）
        long[] f = new long[n];
        f[0] = 1;
        if (n > 1) {
            f[1] = 2;
        }
        for (int i = 2; i < n; i++) {
            f[i] = (f[i - 1] + f[i - 2]) % MOD;
        }

        // 按相邻对的和分组
        HashMap<Long, ArrayList<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            long s = a[i] + a[i + 1];
            groups.computeIfAbsent(s, k -> new ArrayList<>()).add(i);
        }

        long ans = 0;

        // 逐组统计
        for (ArrayList<Integer> pos : groups.values()) {
            long ways = 1;
            int cnt = 1; // 当前连续块长度

            for (int i = 1; i < pos.size(); i++) {
                if (pos.get(i) == pos.get(i - 1) + 1) {
                    cnt++;
                } else {
                    // 一个连续块结束，乘上其贡献
                    ways = ways * f[cnt] % MOD;
                    cnt = 1;
                }
            }

            // 最后一个连续块
            ways = ways * f[cnt] % MOD;

            // 减去一个都不选的情况
            ans = (ans + ways - 1 + MOD) % MOD;
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String[] parts = br.readLine().trim().split(" ");
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(parts[i]);
        }
        System.out.println(solve(n, a));
    }
}
