const long long MOD = 1000000007LL;

// 计算答案的函数
long long solve(int n, const vector<long long>& a) {
    // f[i] 表示长度为 i 的线性序列中，选若干个互不相邻位置的方案数（可一个不选）
    vector<long long> f(n, 0);
    f[0] = 1;
    if (n > 1) {
        f[1] = 2;
