    for (int i = 2; i < n; i++) {
        f[i] = (f[i - 1] + f[i - 2]) % MOD;
    }

    // 按相邻对的和分组
    unordered_map<long long, vector<int> > groups;
    for (int i = 0; i < n - 1; i++) {
        long long s = a[i] + a[i + 1];
        groups[s].push_back(i);
    }

    long long ans = 0;

    // 逐组统计
    for (auto& entry : groups) {
        vector<int>& pos = entry.second;
        long long ways = 1;
        int cnt = 1; // 当前连续块长度

        for (int i = 1; i < (int)pos.size(); i++) {
            if (pos[i] == pos[i - 1] + 1) {
