                ways = ways * f[cnt] % MOD;
                cnt = 1;
            }
        }

        // 最后一个连续块
        ways = ways * f[cnt] % MOD;

        // 减去一个都不选的情况
        ans = (ans + ways - 1 + MOD) % MOD;
    }

    return ans;
}

int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) {
